mapper.select:
SELECT id
FROM wallets
WHERE child_id = #{userId}

SELECT EXISTS (
    SELECT 1
    FROM users
    WHERE id = #{childId}
        AND user_type = 'CHILD'
)

SELECT EXISTS (
    SELECT 1
    FROM family_relations
    WHERE parent_id = #{parentId}
        AND child_id = #{childId}
        AND status = 'ACTIVE'
)

mapper.update:
UPDATE wallets
SET balance = balance + #{amount}
WHERE id = #{walletId}
    AND status = 'ACTIVE'

UPDATE wallets
SET balance = balance - #{amount}
WHERE id = #{walletId}
    AND status = 'ACTIVE'
    AND balance >= #{amount}
